import java.io.*;
import java.util.*;

public class Solution {
    static Scanner sc;
    private static PrintWriter out;
    static long MOD = 1_000_000_000L + 7;

    public static void main(String[] args) throws Exception {
        StringBuilder sb = new StringBuilder();
        if (sb.length() == 0) {
            sc = new Scanner(System.in);
        } else {
            sc = new Scanner(new StringReader(sb.toString()));
        }
        out = new PrintWriter(new OutputStreamWriter(System.out));
        processData();
        runSolution();
        out.flush();
    }

    private static void processData() {
        // No initialization needed
    }

    private static void runSolution() throws IOException {
        int a = sc.nextInt();
        int b = sc.nextInt();
        int l = sc.nextInt() - 1;
        int r = sc.nextInt() - 1;
        int s = r - l + 1;
        for (char first = 'a'; first <= 'z'; first++)
            for (char second = 'a'; second <= 'z'; second++)
                for (char third = 'a'; third <= 'z'; third++)
                    s = Math.min(s, computeS(a, b, l, r, new char[]{first, second, third}));
        out.println(s);
    }

    private static int computeS(int a, int b, int l, int r, char[] pattern) {
        char[] temp = new char[3 * (a + b)];
        for (int segment = 0; segment < 3; segment++) {
            System.arraycopy(generateUniqueChars(temp, segment * (a + b), a), 0, temp, segment * (a + b), a);
            Arrays.fill(temp, segment * (a + b) + a, (segment + 1) * (a + b), pattern[segment]);
        }

        int offset = l % (a + b);
        int length = r - l + 1;
        temp = Arrays.copyOfRange(temp, offset, temp.length);
        temp = Arrays.copyOf(temp, Math.min(temp.length, length));

        boolean[] seen = new boolean[26];
        for (char ch : temp) {
            seen[ch - 'a'] = true;
        }
        int count = 0;
        for (boolean flag : seen) {
            if (flag) count++;
        }
        return count;
    }

    private static char[] generateUniqueChars(char[] buffer, int startIndex, int count) {
        boolean[] used = new boolean[26];
        for (int f = startIndex - 1; f >= 0 && f >= startIndex - count; f--) {
            used[buffer[f] - 'a'] = true;
        }
        char[] result = new char[count];
        char pointer = 'a';
        int cr = 0;
        while (cr < count) {
            while (used[pointer - 'a']) {
                pointer++;
            }
            result[cr++] = pointer++;
        }
        return result;
    }
}
